BEGIN;
UPDATE orders SET status = 'paid' WHERE id = :id;
INSERT INTO outbox_messages(id, type, payload) VALUES (:eventId, 'OrderPaid', :payload);
COMMIT;

INSERT INTO processed_messages(consumer, event_id)
VALUES ('billing', :eventId)
ON CONFLICT DO NOTHING;

SELECT now() - min(created_at) AS oldest_pending
FROM outbox_messages
WHERE published_at IS NULL;
